I use playwright to "открыть страницу авторизации с проверкой HTTP-статуса", async ({ page }) => {
        await (0, navigation_1.openPageWithOverloadRetry)(page, `https://automationexercise.com${LoginPage_1.LoginPage.url}`);
    }

I use playwright to "проверить баннер cookies", async ({ page }) => {
                const consentButton = page.locator(CookieBanner_1.CookieBanner.acceptButton).first();
                try {
                    await consentButton.waitFor({ state: 'visible', timeout: COOKIE_BANNER_TIMEOUT_MS });
                    bannerVisible = true;
                }
                catch (error) {
                    const isTimeoutError = error instanceof Error && error.name === 'TimeoutError';
                    if (!isTimeoutError) {
                        throw error;
                    }
                }
            }

I use playwright to "проверить native validation обязательного email", async ({ page }) => {
        const loginUrl = page.url();
        const emailField = page.locator(AuthForm_1.AuthForm.loginEmailField);
        await page.locator(AuthForm_1.AuthForm.loginSubmitButton).click();
        const validity = await emailField.evaluate(element => {
            const input = element;
            return { valid: input.checkValidity(), valueMissing: input.validity.valueMissing };
        });
        if (validity.valid || !validity.valueMissing) {
            throw new Error('Email field should report valueMissing when submitted empty');
        }
        if (page.url() !== loginUrl) {
            throw new Error(`Login form navigated after native validation: ${page.url()}`);
        }
    }
